scwin.__isShowLastData = function() { var tds = WebSquare.wUnit.getJq("#gridView1_body_tbody .grid_body_row").not('.w2grid_hidedRow').last().find('td'); var count = 0; tds.each(function(index, el) { if (index > 1 && (WebSquare.wUnit.getJq(el).text() != "")) { count++; } }); return count == tds.length - 2; } scwin.unitTest = function() { //Unit WebSquare.wUnit.start(); WebSquare.wUnit.addCommand("pause", "500"); // Test step 3. 샘플화면을 실행 후왼쪽 gridView의 스크롤을 빠르게 내린다. //3. Run the sample screen and quickly scroll down the left gridview. WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1').setTopRowIndex(45)"); WebSquare.wUnit.addCommand("pause", "1000"); // verify step 3. 마지막 row data도 정상적으로 갱신된다.(이전에는 잘못 갱신되거나 일부 값이 보이지 않았음) //3. The last row data is also updated normally (previously incorrectly updated or not showing some values). WebSquare.wUnit.addCommand("assert", "scwin.__isShowLastData()", "true"); WebSquare.wUnit.addCommand("pause", "500"); //Run test and stop WebSquare.wUnit.run(); WebSquare.wUnit.stop(); } scwin.onpageload2 = function() { if (typeof scwin.onpageload === "function") { scwin.onpageload(); } /* for(var i =0;i<50;i++) {
